import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), q = (int) nextLong();
        HashMap<String, String> table = new HashMap<>(2 * n); // "time key" -> original value text
        for (int i = 0; i < n; i++) {
            String t = next(), k = next(), v = next();
            table.put(t + ' ' + k, v);
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String k = next(), t = next();
            if (i > 0) out.append(' ');
            out.append(table.get(t + ' ' + k));
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() string {
		sc.Scan()
		return sc.Text()
	}
	n, _ := strconv.Atoi(next())
	q, _ := strconv.Atoi(next())
	table := make(map[string]string, n) // "time key" -> original value text
	for i := 0; i < n; i++ {
		t := next()
		k := next()
		table[t+" "+k] = next()
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	for i := 0; i < q; i++ {
		k := next()
		t := next()
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(table[t+" "+k])
	}
	w.WriteByte('\n')
}
